package br.edu.exemplo.ia.project.api; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/projects") public class ProjectController { private final ProjectFacade facade; public ProjectController(ProjectFacade facade){this.facade=facade;} record Request(@NotBlank String name,@NotBlank String area){} @PostMapping ProjectView create(@Valid @RequestBody Request r){return facade.create(new CreateProjectCommand(r.name(),r.area()));} @GetMapping List<ProjectView> list(){return facade.list();} }